/* Cluster Lab numerical core v1.0.0. All functions independent of the DOM. */
export const clone=x=>JSON.parse(JSON.stringify(x));
export function rng(seed=42){let a=seed>>>0;return()=>{a+=0x6D2B79F5;let t=a;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296;};}
export const mean=a=>a.reduce((s,x)=>s+x,0)/a.length;
export const d2=(a,b)=>a.reduce((s,x,j)=>s+(x-b[j])**2,0);
export function nearest(x,c){let best=0;for(let i=1;i<c.length;i++)if(d2(x,c[i])<d2(x,c[best]))best=i;return best;}
export function matrix(X){if(!Array.isArray(X)||X.length<2||!Array.isArray(X[0])||!X[0].length||X.some(r=>r.length!==X[0].length||r.some(v=>!Number.isFinite(v)||Math.abs(v)>1e12)))throw Error('Use at least two complete numerical examples with finite values between −10¹² and 10¹².');}
export function parseCSV(text){
 if(text.length>2*1024*1024)throw Error('CSV limit: 2 MB.');
 text=text.replace(/^\uFEFF/,'');let rows=[],row=[],s='',quoted=false,after=false;
 for(let i=0;i<text.length;i++){let c=text[i];if(quoted){if(c==='"'){if(text[i+1]==='"'){s+='"';i++;}else{quoted=false;after=true;}}else s+=c;continue;}
 if(after&&c!==','&&c!=='\r'&&c!=='\n')throw Error('Unexpected text after a quoted field.');
 if(c==='"'){if(s.length||after)throw Error('Quotes must begin a field.');quoted=true;}
 else if(c===','||c==='\n'||c==='\r'){row.push(s.trim());s='';after=false;if(c!==','){if(c==='\r'&&text[i+1]==='\n')i++;if(row.some(v=>v!==''))rows.push(row);row=[];}}
 else s+=c;
 }
 if(quoted)throw Error('A quoted CSV field was not closed.');if(s.length||row.length||after){row.push(s.trim());if(row.some(v=>v!==''))rows.push(row);}
 if(rows.length<3)throw Error('Include a header and at least two data rows.');let headers=rows.shift();if(headers.length>25||headers.some(x=>!x)||new Set(headers).size!==headers.length)throw Error('Use 1–25 unique, nonempty column names.');if(rows.length>500)throw Error('Limit: 500 examples. Split your dataset.');if(rows.some(r=>r.length!==headers.length))throw Error('Every row must have the same number of fields as the header.');
 if(rows.flat().some(v=>/^[+-]?(?:infinity|nan)$/i.test(v)||(/^[-+]?\d.*[eE][-+]?\d+$/.test(v)&&!Number.isFinite(Number(v)))))throw Error('NaN and Infinity are not supported. Use a blank cell for missing data.');
 return {headers,rows};
}
export function describe(data){return data.headers.map((name,j)=>{let vals=data.rows.map(r=>r[j]).filter(v=>v!==''&&v!==null),numeric=vals.length>0&&vals.every(v=>Number.isFinite(Number(v)));let a=numeric?vals.map(Number):[];return{name,numeric,missing:data.rows.length-vals.length,min:a.length?Math.min(...a):null,max:a.length?Math.max(...a):null,constant:a.length>0&&Math.min(...a)===Math.max(...a),reserved:/^(id|name|label|class|category|target|cluster|song|object)([ _-]|$)/i.test(name)};});}
export function prepare(data,features,scale=true,missing='drop'){
 if(!['drop','mean'].includes(missing))throw Error('Choose remove rows or mean imputation.');if(features.length<2)throw Error('Select at least two numerical features.');
 const desc=describe(data);if(new Set(features).size!==features.length||features.some(f=>!desc[f]?.numeric||desc[f].reserved))throw Error('Use numerical features; names, IDs, and category labels are metadata.');
 let raw=data.rows.map(r=>features.map(f=>r[f]===''||r[f]===null?null:Number(r[f])));let imputes=features.map((_,j)=>mean(raw.map(r=>r[j]).filter(v=>v!==null)));let indices=[];raw=raw.filter((r,i)=>{if(missing==='drop'&&r.includes(null))return false;indices.push(i);return true;});let filled=0;raw=raw.map(r=>r.map((v,j)=>{if(v===null){filled++;return imputes[j];}return v;}));matrix(raw);
 const means=features.map((_,j)=>mean(raw.map(r=>r[j]))),stds=features.map((_,j)=>Math.sqrt(mean(raw.map(r=>(r[j]-means[j])**2))));let keep=stds.map((s,j)=>s>1e-12?j:-1).filter(j=>j>=0);let excluded=features.filter((_,j)=>!keep.includes(j)).map(f=>data.headers[f]);if(keep.length<2)throw Error('At least two nonconstant features must remain after cleaning.');
 const prep={features:keep.map(j=>features[j]),names:keep.map(j=>data.headers[features[j]]),means:keep.map(j=>means[j]),stds:keep.map(j=>stds[j]),imputes:keep.map(j=>imputes[j]),scale,missing,excluded};raw=raw.map(r=>keep.map(j=>r[j]));const X=raw.map(r=>transform(r,prep));return{X,raw,indices,prep,removed:data.rows.length-raw.length,filled};
}
export function transform(values,p){if(values.length!==p.names.length)throw Error('Feature count does not match the model.');return values.map((v,j)=>{if(v===''||v===null){if(p.missing==='mean')v=p.imputes[j];else throw Error('Complete every feature for a new example.');}v=Number(v);if(!Number.isFinite(v)||Math.abs(v)>1e12)throw Error('Enter finite numerical values between −10¹² and 10¹².');return p.scale?(v-p.means[j])/p.stds[j]:v;});}
export function initialize(X,k,random){let c=[X[Math.floor(random()*X.length)].slice()];while(c.length<k){let weights=X.map(x=>Math.min(...c.map(y=>d2(x,y)))),total=weights.reduce((a,b)=>a+b,0),r=random()*total,index=weights.findIndex(w=>(r-=w)<0);if(index<0)index=weights.findIndex(w=>w>0);c.push(X[index].slice());}return c;}
export function createStepper(X,k,seed=42,initial=null,maxIter=300){matrix(X);if(!Number.isInteger(k)||k<1||k>12||k>new Set(X.map(x=>JSON.stringify(x))).size)throw Error('K must be 1–12 and no larger than the number of distinct examples.');if(!Number.isInteger(maxIter)||maxIter<1||maxIter>1000)throw Error('Iteration limit must be 1–1000.');if(initial&&(initial.length!==k||initial.some(c=>c.length!==X[0].length||c.some(v=>!Number.isFinite(v)))))throw Error('Invalid initial centers.');return{X,k,centers:initial?clone(initial):initialize(X,k,rng(seed)),labels:null,phase:'initial',iteration:0,done:false,converged:false,maxIter,repairs:0};}
export function advance(s){if(s.done)return s;if(s.phase==='initial'||s.phase==='update'){s.labels=s.X.map(x=>nearest(x,s.centers));s.phase='assign';return s;}
 let counts=Array(s.k).fill(0);s.labels.forEach(l=>counts[l]++);
 for(let c=0;c<s.k;c++)if(!counts[c]){let candidate=-1,best=-1;s.X.forEach((x,i)=>{let d=d2(x,s.centers[s.labels[i]]);if(counts[s.labels[i]]>1&&d>best){best=d;candidate=i;}});counts[s.labels[candidate]]--;s.labels[candidate]=c;counts[c]++;s.repairs++;}
 s.centers=Array.from({length:s.k},(_,c)=>s.X[0].map((_,j)=>s.X.reduce((a,x,i)=>a+(s.labels[i]===c?x[j]:0),0)/counts[c]));s.iteration++;s.phase='update';
 const next=s.X.map(x=>nearest(x,s.centers));if(next.every((l,i)=>l===s.labels[i])){s.done=true;s.converged=true;}else if(s.iteration>=s.maxIter){s.done=true;s.labels=next;}
 return s;
}
export function finish(s){return{centers:clone(s.centers),labels:s.labels.slice(),iterations:s.iteration,converged:s.converged,repairs:s.repairs,inertia:s.X.reduce((a,x,i)=>a+d2(x,s.centers[s.labels[i]]),0)};}
export function fit(X,k,{seed=42,restarts=10,maxIter=300,initial=null}={}){if(!Number.isInteger(restarts)||restarts<1||restarts>20)throw Error('Restarts must be 1–20.');let best=null;for(let n=0;n<(initial?1:restarts);n++){let s=createStepper(X,k,seed+n,initial,maxIter);while(!s.done)advance(s);let r=finish(s);if(!best||(r.converged&&!best.converged)||(r.converged===best.converged&&r.inertia<best.inertia))best=r;}return best;}
export function silhouette(X,labels){const groups=[...new Set(labels)];if(groups.length<2||groups.length>=X.length)return null;return mean(X.map((x,i)=>{let own=labels.filter(l=>l===labels[i]).length;if(own===1)return 0;let sums=new Map(groups.map(g=>[g,0])),counts=new Map(groups.map(g=>[g,0]));X.forEach((y,j)=>{if(i!==j){sums.set(labels[j],sums.get(labels[j])+Math.sqrt(d2(x,y)));counts.set(labels[j],counts.get(labels[j])+1);}});let a=sums.get(labels[i])/(own-1),b=Math.min(...groups.filter(g=>g!==labels[i]).map(g=>sums.get(g)/counts.get(g)));return Math.max(a,b)===0?0:(b-a)/Math.max(a,b);}));}
/* Symmetric Jacobi eigendecomposition: tested against sklearn PCA. */
export function pca(X,componentsCount=2){matrix(X);if(![2,3].includes(componentsCount)||componentsCount>Math.min(X.length,X[0].length))throw Error("PCA needs enough examples and features for the requested dimensions.");const d=X[0].length,m=X[0].map((_,j)=>mean(X.map(r=>r[j]))),Z=X.map(r=>r.map((v,j)=>v-m[j]));let A=Array.from({length:d},(_,i)=>Array.from({length:d},(_,j)=>Z.reduce((s,r)=>s+r[i]*r[j],0)/(X.length-1))),V=Array.from({length:d},(_,i)=>Array.from({length:d},(_,j)=>+(i===j)));
 for(let iter=0;iter<100*d*d;iter++){let p=0,q=1;for(let i=0;i<d;i++)for(let j=i+1;j<d;j++)if(Math.abs(A[i][j])>Math.abs(A[p][q])){p=i;q=j;}if(Math.abs(A[p][q])<1e-12*Math.max(1,...A.map((r,i)=>Math.abs(r[i]))))break;let phi=.5*Math.atan2(2*A[p][q],A[q][q]-A[p][p]),c=Math.cos(phi),s=Math.sin(phi),ap=A[p][p],aq=A[q][q],pq=A[p][q];for(let i=0;i<d;i++)if(i!==p&&i!==q){let x=A[i][p],y=A[i][q];A[i][p]=A[p][i]=c*x-s*y;A[i][q]=A[q][i]=s*x+c*y;}A[p][p]=c*c*ap-2*s*c*pq+s*s*aq;A[q][q]=s*s*ap+2*s*c*pq+c*c*aq;A[p][q]=A[q][p]=0;for(let i=0;i<d;i++){let x=V[i][p],y=V[i][q];V[i][p]=c*x-s*y;V[i][q]=s*x+c*y;}}
 let order=Array.from({length:d},(_,i)=>i).sort((a,b)=>A[b][b]-A[a][a]),total=order.reduce((a,i)=>a+Math.max(0,A[i][i]),0);let components=order.slice(0,componentsCount).map(i=>V.map(r=>r[i]));return{means:m,components,variance:order.slice(0,componentsCount).map(i=>total?Math.max(0,A[i][i])/total:0),points:Z.map(r=>components.map(c=>r.reduce((a,v,j)=>a+v*c[j],0)))};
}
export function projectPCA(X,p){return X.map(r=>p.components.map(c=>r.reduce((s,v,j)=>s+(v-p.means[j])*c[j],0)));}
export function csv(data){return data.map(r=>r.map(v=>{let s=String(v??'');if(/^[=+@\-]/.test(s)&&!Number.isFinite(Number(s)))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}).join(',')).join('\r\n');}
export function tsneSettings(n,o){if(![2,3].includes(o.dimensions??2))throw Error("Choose 2D or 3D for t-SNE.");if(!Number.isFinite(o.perplexity)||o.perplexity<1||o.perplexity>=n)throw Error('Perplexity must be at least 1 and smaller than the example count.');if(!Number.isInteger(o.iterations)||o.iterations<250||o.iterations>1500)throw Error('Use 250–1500 t-SNE iterations.');if(!Number.isFinite(o.learningRate)||o.learningRate<=0||o.learningRate>1000)throw Error('Use a t-SNE learning rate above 0 and at most 1000.');if(!Number.isInteger(o.seed))throw Error('Use an integer random seed.');}
export function validateModel(m){if(m?.schema!==1||m.kind!=='cluster-lab-model'||!m.prep||!Array.isArray(m.centers))throw Error('This is not a Cluster Lab v1 model.');const p=m.prep,d=p.names?.length;if(!d||d>25||!Array.isArray(p.names)||p.names.some(x=>typeof x!=='string')||new Set(p.names).size!==d)throw Error('Invalid model feature names.');for(const key of ['means','stds','imputes'])if(!Array.isArray(p[key])||p[key].length!==d||p[key].some(x=>!Number.isFinite(x)))throw Error('Invalid preprocessing values.');if(p.stds.some(x=>x<=0)||typeof p.scale!=='boolean'||!['drop','mean'].includes(p.missing)||!m.centers.length||m.centers.length>12||m.centers.some(c=>!Array.isArray(c)||c.length!==d||c.some(v=>!Number.isFinite(v))))throw Error('Invalid model centers or preprocessing.');return m;}
